/* tiles2d_layouts: TileMap2D layouts that are not squares. One scene (assets/main.cwscene, generated by make.mjs)
 * holds three islands: ISOMETRIC diamonds, HEX_ROWS (pointy-top hexagons) and HEX_COLUMNS (flat-top). Each map
 * has a wall of rock across it with one gap, a TileCollision2D (the outline of its solid diamonds or hexagons as
 * chains) and a NavigationRegion2D; two walkers a map trade places through the gap, their cells and goals given
 * in the scene as cells. Input-free.
 *
 * Debug fields, one of each per map (iso, hex rows, hex columns): lay.reached, lay.chains, lay.segments,
 * lay.walkable, lay.crowd_hash; lay.probe (the cell under a fixed point of each map), lay.round_trip (cells
 * whose middle maps back to the cell: all of them). */
#include "cartwheel/debug.h"
#include "cartwheel/nav2d.h"
#include "cartwheel/physics_nodes.h"
#include "cartwheel/platform.h"
#include "cartwheel/scene2d.h"
#include "cartwheel/scene_file.h"

static const char *const MAPS[3] = { "Iso", "HexRows", "HexColumns" };
static int32_t reached[3], chains[3], segments[3], walkable[3], probe[6], round_trip[3], tick;
static uint32_t crowd_hash[3];

/* #region walker */
typedef struct walker {
  cw_vec2 cell, goal; /* cells of the map it is a child of */
} walker;
static const cw_prop walker_props[] = {
  CW_PROP_FIELD(walker, cell, CW_T_VEC2, CW_PROP_DEFAULT, "The cell it starts in."),
  CW_PROP_FIELD(walker, goal, CW_T_VEC2, CW_PROP_DEFAULT, "The cell it walks to, and back from."),
  CW_PROP_END,
};
static cw_node_type walker_type = { .name = "LayoutWalker", .parent = "Node2D", .data_size = sizeof(walker), .props = walker_props };

/* a walker that arrives turns round: its goal and its start trade places */
static void on_reached(cw_node agent, const cw_value *args, int argc, void *user) {
  (void)args, (void)argc;
  cw_node body = cw_node_parent(agent), map = cw_node_parent(body);
  walker *w = cw_node_data(body, "LayoutWalker");
  cw_vec2 t = w->cell;
  w->cell = w->goal, w->goal = t;
  /* the middle of a cell, whatever the map's layout */
  cw_vec2 to = cw_tilemap2d_cell_center(map, (int)w->goal.x, (int)w->goal.y);
  cw_node_set(agent, "target_position", cw_val_vec2(to.x, to.y));
  reached[(int)(intptr_t)user]++;
}

static void start(cw_node root) {
  for (int m = 0; m < 3; m++) {
    cw_node map = cw_node_get(root, MAPS[m]);
    for (int i = 0; i < 2; i++) {
      cw_node body = cw_node_get(map, cw_frame_printf("Walker%d", i)), agent = cw_node_get(body, "Agent");
      walker *w = cw_node_data(body, "LayoutWalker");
      cw_node2d_set_position(body, cw_tilemap2d_cell_center(map, (int)w->cell.x, (int)w->cell.y));
      cw_vec2 to = cw_tilemap2d_cell_center(map, (int)w->goal.x, (int)w->goal.y);
      cw_node_set(agent, "target_position", cw_val_vec2(to.x, to.y));
      cw_connect(agent, "target_reached", agent, NULL, on_reached, (void *)(intptr_t)m, 0);
    }
  }
}
/* #endregion */

static void init(void *u) {
  (void)u;
  cw_debug_field("lay.reached", reached, CW_DBG_I32, 3);
  cw_debug_field("lay.chains", chains, CW_DBG_I32, 3);
  cw_debug_field("lay.segments", segments, CW_DBG_I32, 3);
  cw_debug_field("lay.walkable", walkable, CW_DBG_I32, 3);
  cw_debug_field("lay.probe", probe, CW_DBG_I32, 6);
  cw_debug_field("lay.round_trip", round_trip, CW_DBG_I32, 3);
  cw_debug_field("lay.crowd_hash", crowd_hash, CW_DBG_U32, 3);
}

static void fixed(void *u, double dt) {
  (void)u, (void)dt;
  cw_node root = cw_node_get(cw_tree_root(cw_scene_app_tree()), "Layouts");
  if (!cw_node_valid(root)) return;
  if (++tick == 1) start(root);
  for (int m = 0; m < 3; m++) {
    cw_node map = cw_node_get(root, MAPS[m]), nav = cw_node_get(map, "Nav");
    cw_tile_collision2d_stats s = cw_tile_collision2d_stats_get(cw_node_get(map, "Solid"));
    chains[m] = s.chains, segments[m] = s.segments;
    walkable[m] = cw_navgrid_get_stats(cw_nav_region2d_grid(nav)).walkable;
    crowd_hash[m] = (uint32_t)cw_crowd2d_hash(cw_nav_region2d_crowd(nav));
    /* #region cells */
    /* the cell under a point of the map, and back: every cell's middle lies in that cell */
    cw_tilemap2d_local_to_cell(map, cw_v2(37, 41), &probe[2 * m], &probe[2 * m + 1]);
    int w, h, ok = 0;
    cw_tilemap2d_size(map, &w, &h);
    for (int y = 0; y < h; y++)
      for (int x = 0; x < w; x++) {
        int cx, cy;
        cw_tilemap2d_local_to_cell(map, cw_tilemap2d_cell_center(map, x, y), &cx, &cy);
        ok += cx == x && cy == y;
      }
    round_trip[m] = ok;
    /* #endregion */
  }
}

cw_app_desc cw_main(int argc, char **argv) {
  (void)argc, (void)argv;
  cw_scene_register_builtin_types();
  cw_node_type_register(&walker_type);
  static cw_app_desc base = { .title = "tiles2d_layouts", .width = 960, .height = 540, .debug = true, .init = init, .fixed_update = fixed };
  return cw_scene_app("main.cwscene", &base);
}
